document.addEventListener('DOMContentLoaded', function() {
    // Find all expand buttons
    const expandButtons = document.querySelectorAll('.flexi-imagetext-image__expand');
    
    expandButtons.forEach(function(button) {
        button.addEventListener('click', function(e) {
            e.preventDefault();
            
            // Find the parent image container
            const imageContainer = this.closest('.flexi-imagetext-image');
            
            // Find the img tag within the container
            const img = imageContainer.querySelector('img');
            
            if (img && img.src) {
                // Open the image URL in a new tab
                window.open(img.src, '_blank');
            }
        });
    });

});;
